574	func TestReopenPreservesStateAndRecomputesExpiry(t *testing.T) {
575		dir := t.TempDir()
576		clk := &fakeClock{t: time.Date(2026, 3, 1, 8, 0, 0, 0, time.UTC)}
577		open := func() *Store {
578			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
579			if err != nil {
580				t.Fatalf("open: %v", err)
581			}
582			return s
583		}
584	
585		s := open()
586		p, err := s.RegisterPatient(doc, "持久化患者")
587		if err != nil {
588			t.Fatal(err)
589		}
590		e, _ := s.AddEncounter(doc, p.ID, time.Time{})
591		rec, _ := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "v1")
592		v1, _ := s.ActivateRecord(doc, rec.ID)
593		v2, _ := s.CorrectRecord(doc, rec.ID, 1, "v2", "原因A")
594	
595		// 授权：在当前窗口内有效，但未来会到期。
596		grantStart := clk.t.Add(-time.Hour)
597		grantEnd := clk.t.Add(2 * time.Hour)
598		a, _ := s.Grant(doc, p.ID, rcv.ID, []Scope{{EncounterID: e.ID, Category: Diagnosis}}, grantStart, grantEnd)
599		_ = v1
600		if err := s.Close(); err != nil {
601			t.Fatal(err)
602		}
603	
604		// 重开：档案、版本、授权状态、审计都在。
605		s2 := open()
606		chart, err := s2.Chart(doc, p.ID)
607		if err != nil {
608			t.Fatal(err)
609		}
610		if len(chart.Records) != 1 || len(chart.Records[0].Versions) != 2 {
611			t.Fatalf("versions lost: %+v", chart.Records)
612		}
613		h := chart.Records[0]
614		if h.CurrentVersion.ID != v2.ID || h.Versions[0].Content != "v1" || h.Versions[1].Reason != "原因A" {
615			t.Fatalf("history not preserved: %+v", h)
616		}
617		if len(chart.AuditEvents) != 3 {
618			t.Fatalf("audit lost: %d", len(chart.AuditEvents))
619		}
620		gotAuth, err := s2.GetAuthorization(doc, p.ID, a.ID)
621		if err != nil {
622			t.Fatalf("authorization lost: %v", err)
623		}
624		if gotAuth.RevokedAt != nil {
625			t.Fatal("authorization should not be revoked")
626		}
627		// 窗口内可读。
628		if res, err := s2.Read(rcv, p.ID, e.ID, Diagnosis); err != nil || len(res.Records) != 1 || res.Records[0].Content != "v2" {
629			t.Fatalf("read after reopen: %+v %v", res, err)
630		}
631		// 撤回后重开：撤回状态与撤回审计持久保留，接收方仍被拒绝。
632		if err := s2.Revoke(doc, p.ID, a.ID); err != nil {
633			t.Fatal(err)
634		}
635		if err := s2.Close(); err != nil {
636			t.Fatal(err)
637		}
638	
639		s2b := open()
640		gotAuth2, err := s2b.GetAuthorization(doc, p.ID, a.ID)
641		if err != nil {
642			t.Fatalf("authorization lost after reopen: %v", err)
643		}
644		if gotAuth2.RevokedAt == nil {
645			t.Fatal("revocation not persisted across reopen")
646		}
647		if _, err := s2b.Read(rcv, p.ID, e.ID, Diagnosis); !errors.Is(err, ErrAccessDenied) {
648			t.Fatalf("revoked grant must deny after reopen: %v", err)
649		}
650		// 重开后重复撤回仍幂等。
651		rn1 := len(mustAudit(t, s2b, p.ID))
652		if err := s2b.Revoke(doc, p.ID, a.ID); err != nil {
653			t.Fatal(err)
654		}
655		if rn2 := len(mustAudit(t, s2b, p.ID)); rn2 != rn1 {
656			t.Fatalf("idempotent revoke after reopen added events: %d -> %d", rn1, rn2)
657		}
658		if err := s2b.Close(); err != nil {
659			t.Fatal(err)
660		}
661	
662		// 时间推进到授权到期之后再次打开：到期按本次读取时间判断。
663		clk.t = grantEnd.Add(time.Hour)
664		s3 := open()
665		t.Cleanup(func() { _ = s3.Close() })
666		if _, err := s3.Read(rcv, p.ID, e.ID, Diagnosis); !errors.Is(err, ErrAccessDenied) {
667			t.Fatalf("expired grant must deny after reopen: %v", err)
668		}
669	
670		// 停用状态持久化，且重开后重复停用不再产生事件。
671		if err := s3.DeactivatePatient(doc, p.ID); err != nil {
672			t.Fatal(err)
673		}
674		if err := s3.Close(); err != nil {
675			t.Fatal(err)
676		}
677		s4 := open()
678		t.Cleanup(func() { _ = s4.Close() })
679		pat, _ := s4.GetPatient(doc, p.ID)
680		if !pat.Deactivated {
681			t.Fatal("deactivation not persisted")
682		}
683		n1 := len(mustAudit(t, s4, p.ID))
684		if err := s4.DeactivatePatient(doc, p.ID); err != nil {
685			t.Fatal(err)
686		}
687		if n2 := len(mustAudit(t, s4, p.ID)); n2 != n1 {
688			t.Fatalf("idempotent deactivate after reopen added events: %d -> %d", n1, n2)
689		}
690	}
