725	// ---- 返回的授权是独立副本 ----
726	
727	func TestReturnedAuthorizationIsDetachedCopy(t *testing.T) {
728		s, clk := newTestStore(t)
729		pid, eid := setupPatientEncounter(t, s)
730	
731		mkRec := func(content string) ID {
732			t.Helper()
733			r, err := s.CreateDraft(doc, pid, eid, Diagnosis, content)
734			if err != nil {
735				t.Fatalf("create draft: %v", err)
736			}
737			if _, err := s.ActivateRecord(doc, r.ID); err != nil {
738				t.Fatalf("activate: %v", err)
739			}
740			return r.ID
741		}
742		d1 := mkRec("d1")
743		d2 := mkRec("d2")
744		d3 := mkRec("d3")
745	
746		t0 := clk.t.Add(-time.Hour)
747		t1 := clk.t.Add(time.Hour)
748	
749		// 整类范围：把返回结果中的类别改成医嘱，不改变真实的诊断授权。
750		ga, err := s.Grant(doc, pid, "rcv-a", []Scope{{EncounterID: eid, Category: Diagnosis}}, t0, t1)
751		if err != nil {
752			t.Fatalf("grant: %v", err)
753		}
754		ga.Scopes[0].Category = Order
755		got, err := s.GetAuthorization(doc, pid, ga.ID)
756		if err != nil {
757			t.Fatalf("get auth: %v", err)
758		}
759		if len(got.Scopes) != 1 || got.Scopes[0].Category != Diagnosis {
760			t.Fatalf("stored scope rewritten via returned value: %+v", got.Scopes)
761		}
762		if _, err := s.Read(rcv, pid, eid, Order); !errors.Is(err, ErrAccessDenied) {
763			t.Fatalf("receiver read order err = %v, want ErrAccessDenied", err)
764		}
765		if res, err := s.Read(rcv, pid, eid, Diagnosis); err != nil || len(res.Records) != 3 {
766			t.Fatalf("receiver read diagnosis = %+v, %v", res, err)
767		}
768	
769		// 限定范围：把返回结果中的记录标识换成同类第三条记录，
770		// 第三条不能因此进入授权；原本两条仍按既有规则可读。
771		sa, err := s.GrantSelective(doc, pid, "rcv-b", nil, []RecordSelection{
772			{EncounterID: eid, Category: Diagnosis, RecordID: d2},
773			{EncounterID: eid, Category: Diagnosis, RecordID: d1},
774		}, t0, t1)
775		if err != nil {
776			t.Fatalf("grant selective: %v", err)
777		}
778		if len(sa.Selections) != 2 {
779			t.Fatalf("selections = %+v", sa.Selections)
780		}
781		sa.Selections[0].RecordID = d3
782		gotSel, err := s.GetAuthorization(doc, pid, sa.ID)
783		if err != nil {
784			t.Fatalf("get selective auth: %v", err)
785		}
786		selIDs := map[ID]bool{}
787		for _, sel := range gotSel.Selections {
788			selIDs[sel.RecordID] = true
789		}
790		if len(selIDs) != 2 || !selIDs[d1] || !selIDs[d2] || selIDs[d3] {
791			t.Fatalf("stored selections rewritten via returned value: %+v", gotSel.Selections)
792		}
793	
794		// 只改了返回结果就把未覆盖的记录夹带进交换：拒绝且不留下交换或审计。
795		audBefore, err := s.AuditEvents(doc, pid)
796		if err != nil {
797			t.Fatalf("audit: %v", err)
798		}
799		if _, err := s.CreateExchange(doc, pid, "rcv-b", sa.ID, []ID{d3}, "req-denied"); !errors.Is(err, ErrAccessDenied) {
800			t.Fatalf("exchange with uncovered record err = %v, want ErrAccessDenied", err)
801		}
802		if xs, err := s.ListExchanges(doc, pid); err != nil || len(xs) != 0 {
803			t.Fatalf("denied exchange persisted: %+v, %v", xs, err)
804		}
805		audAfter, _ := s.AuditEvents(doc, pid)
806		if len(audAfter) != len(audBefore) {
807			t.Fatalf("denied exchange left audit: %d -> %d", len(audBefore), len(audAfter))
808		}
809		// 原本获准的记录不因此失去授权。
810		if _, err := s.CreateExchange(doc, pid, "rcv-b", sa.ID, []ID{d1, d2}, "req-ok"); err != nil {
811			t.Fatalf("exchange with covered records: %v", err)
812		}
813	
814		// 从同一授权取得的多份结果彼此独立。
815		c1, err := s.GetAuthorization(doc, pid, ga.ID)
816		if err != nil {
817			t.Fatalf("get copy 1: %v", err)
818		}
819		c2, err := s.GetAuthorization(doc, pid, ga.ID)
820		if err != nil {
821			t.Fatalf("get copy 2: %v", err)
822		}
823		c1.Scopes[0].Category = Order
824		if c2.Scopes[0].Category != Diagnosis {
825			t.Fatalf("mutating one copy affected another: %+v", c2.Scopes)
826		}
827		// ListAuthorizations 的返回结果同样只是副本。
828		la, err := s.ListAuthorizations(doc, pid, "rcv-a")
829		if err != nil || len(la) != 1 {
830			t.Fatalf("list auths = %+v, %v", la, err)
831		}
832		la[0].Scopes[0].Category = Order
833		gotAgain, _ := s.GetAuthorization(doc, pid, ga.ID)
834		if gotAgain.Scopes[0].Category != Diagnosis {
835			t.Fatalf("stored scope rewritten via listed value: %+v", gotAgain.Scopes)
836		}
837	
838		// 已撤回授权：改返回结果中的撤回时间或本地清空它，
839		// 不能更改真实撤回时间或恢复访问。
840		if err := s.Revoke(doc, pid, ga.ID); err != nil {
841			t.Fatalf("revoke: %v", err)
842		}
843		ra, err := s.GetAuthorization(doc, pid, ga.ID)
844		if err != nil {
845			t.Fatalf("get revoked auth: %v", err)
846		}
847		if ra.RevokedAt == nil {
848			t.Fatal("revoked auth has no revoked-at")
849		}
850		saved := *ra.RevokedAt
851		*ra.RevokedAt = saved.Add(48 * time.Hour)
852		ra.RevokedAt = nil
853		ra2, err := s.GetAuthorization(doc, pid, ga.ID)
854		if err != nil {
855			t.Fatalf("re-get revoked auth: %v", err)
856		}
857		if ra2.RevokedAt == nil || !ra2.RevokedAt.Equal(saved) {
858			t.Fatalf("revoked-at rewritten via returned value: %v, want %v", ra2.RevokedAt, saved)
859		}
860		if _, err := s.Read(rcv, pid, eid, Diagnosis); !errors.Is(err, ErrAccessDenied) {
861			t.Fatalf("read after local clear of revoked-at err = %v, want ErrAccessDenied", err)
862		}
863	}
