func TestRevokeIndependentAndIdempotent(t *testing.T) {
	s, clk := newTestStore(t)
	pid, eid := setupPatientEncounter(t, s)
	rec, _ := s.CreateDraft(doc, pid, eid, Diagnosis, "x")
